cd /tmp && cat > StackAllocNint.cs << 'EOF'
using System;

class Program
{
    static void Main()
    {
        Span<nint> nints = stackalloc nint[4];
        nints[0] = 42;
        nints[1] = nint.MaxValue;
        nints[2] = nint.MinValue;
        nints[3] = (nint)123456789;

        for (int i = 0; i < nints.Length; i++)
            Console.WriteLine($"nints[{i}] = {nints[i]}");

        Span<nuint> nuints = stackalloc nuint[3];
        nuints[0] = 0;
        nuints[1] = nuint.MaxValue;
        nuints[2] = (nuint)999;

        for (int i = 0; i < nuints.Length; i++)
            Console.WriteLine($"nuints[{i}] = {nuints[i]}");

        Console.WriteLine($"\nsizeof(nint) = {sizeof(nint)}");
        Console.WriteLine("stackalloc Span<nint> and Span<nuint> works!");
    }
}
EOF
dotnet-script StackAllocNint.cs 2>/dev/null || dotnet run --project . 2>/dev/null || (mkdir -p /tmp/nint-test && cd /tmp/nint-test && dotnet new console --force -q && cp /tmp/StackAllocNint.cs Program.cs && dotnet run --allow-unsafe)

